<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,useLoad,useCommand,PageHeader,Feedback,EmptyState,StatusBadge,money,session,type Order} from '@tradeflow/ui'
import {useRows,text,permits} from '../data'
import Pagination from '../components/Pagination.vue'
const list=useRows(()=>'/api/v1/merchant/orders','array')
const selected=ref(''),visible=ref(false),shipping=ref(false),carrier=ref(''),tracking=ref(''),notice=ref('')
const detail=useLoad<Order>(signal=>api('/api/v1/merchant/orders/'+encodeURIComponent(selected.value),{signal}))
const command=useCommand('admin-shipment')
const address=useLoad<{receiverName:string;receiverPhone:string;region:string;detailAddress:string}>(signal=>api('/api/v1/merchant/orders/'+encodeURIComponent(selected.value)+'/shipping-address',{signal}))
let addressTimer:ReturnType<typeof setTimeout>|undefined
// 用户主动查看且服务端审核并审计；明文只保留当前弹窗内存，两分钟或关闭后清除。
async function showAddress(){const g=generation;clearTimeout(addressTimer);address.clear();await address.reload();if(g===generation&&visible.value)addressTimer=setTimeout(()=>address.clear(),120000)}
function hideAddress(){clearTimeout(addressTimer);address.clear()}

let generation=0
onBeforeUnmount(()=>{generation++;hideAddress()})
async function open(no:unknown){generation++;hideAddress();selected.value=String(no);visible.value=true;shipping.value=false;carrier.value='';tracking.value='';detail.clear();await detail.reload()}
function close(){generation++;hideAddress();visible.value=false;shipping.value=false;detail.clear()}
/** 仅使用商家专用详情，不请求买家接口；发货资格完全以服务端当前allowedActions为准，未知结果沿用原命令键。 */
async function ship(){const g=generation,no=selected.value;notice.value='';if(!carrier.value.trim()||!tracking.value.trim())return;const body={carrier:carrier.value.trim(),trackingNo:tracking.value.trim()};const result=await command.run('ship:'+no,body,key=>api('/api/v1/merchant/orders/'+encodeURIComponent(no)+'/ship',{method:'POST',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;hideAddress();shipping.value=false;notice.value='发货请求已返回，请以订单最新状态和物流信息为准。';await detail.reload();await list.reload()}
watch(()=>detail.data.value,current=>{if(!permits(current,'VIEW_SHIPPING_ADDRESS'))hideAddress()})
watch(()=>session.user?.userId,()=>{close();list.clear();notice.value=''})
onMounted(()=>list.reload())
</script>
<template><PageHeader title="订单履约" description="查看所属商家订单，依据当前履约资格提交整单发货。"/><section class="panel"><div class="toolbar"><h2>所属订单</h2><ElButton :loading="list.loading.value" @click="list.reload">刷新列表</ElButton></div><Feedback :loading="list.loading.value" :error="list.error.value"/><template v-if="!list.loading.value&&!list.error.value"><EmptyState v-if="!list.items.value.length" title="当前页暂无订单"/><ElTable v-else :data="list.items.value"><ElTableColumn label="订单编号" min-width="300"><template #default="{row}"><span class="mono">{{text(row.order_no)}}</span></template></ElTableColumn><ElTableColumn label="订单状态" width="140"><template #default="{row}"><StatusBadge :status="text(row.status)"/></template></ElTableColumn><ElTableColumn label="实付金额" width="130"><template #default="{row}">{{money(Number(row.total_amount_cents))}}</template></ElTableColumn><ElTableColumn label="库存同步" min-width="130"><template #default="{row}">{{text(row.stock_sync_status)}}</template></ElTableColumn><ElTableColumn label="创建时间" min-width="210"><template #default="{row}">{{text(row.created_at)}}</template></ElTableColumn><ElTableColumn label="操作" width="130"><template #default="{row}"><ElButton @click="open(row.order_no)">查看订单</ElButton></template></ElTableColumn></ElTable></template><Pagination :page="list.page.value" :count="list.items.value.length" :has-next="list.hasNext.value" :loading="list.loading.value" @change="list.change"/></section>
<ElDialog :model-value="visible" title="商家订单详情" width="860px" @close="close"><Feedback :loading="detail.loading.value" :error="detail.error.value"/><template v-if="detail.data.value"><p class="mono">{{detail.data.value.orderNo}}</p><dl class="detail-grid"><div><dt>订单状态</dt><dd><StatusBadge :status="detail.data.value.status"/></dd></div><div><dt>金额</dt><dd>{{money(detail.data.value.amountCents)}}</dd></div><div><dt>库存同步 / 履约锁</dt><dd>{{detail.data.value.stockSyncStatus}} / {{detail.data.value.fulfillmentLock}}</dd></div></dl><ElTable :data="detail.data.value.items"><ElTableColumn prop="productName" label="商品快照" min-width="180"/><ElTableColumn prop="specification" label="规格" min-width="160"/><ElTableColumn prop="quantity" label="数量" width="80"/><ElTableColumn label="购买单价" width="120"><template #default="{row}">{{money(row.unitPriceCents)}}</template></ElTableColumn></ElTable><h3 class="section-title">收货资料</h3><p class="muted">仅限当前订单履约使用，查看会保留审计，两分钟后自动隐藏。</p><ElButton v-if="permits(detail.data.value,'VIEW_SHIPPING_ADDRESS')" :loading="address.loading.value" @click="showAddress">按需查看收货资料</ElButton><ElButton v-if="address.data.value" @click="hideAddress">隐藏资料</ElButton><Feedback :loading="address.loading.value" :error="address.error.value"/><dl v-if="address.data.value" class="detail-grid"><div><dt>收货人</dt><dd>{{address.data.value.receiverName}}</dd></div><div><dt>联系电话</dt><dd>{{address.data.value.receiverPhone}}</dd></div><div><dt>收货地址</dt><dd>{{address.data.value.region}} {{address.data.value.detailAddress}}</dd></div></dl><h3 class="section-title">物流信息</h3><p v-if="detail.data.value.shipment">{{detail.data.value.shipment.carrier}} · {{detail.data.value.shipment.trackingNo}}</p><p v-else class="muted">尚无已确认物流信息</p><p v-if="notice" class="notice" role="status">{{notice}}</p><ElButton v-if="permits(detail.data.value,'SHIP')&&!shipping" type="primary" @click="shipping=true">填写发货物流</ElButton><ElForm v-if="shipping&&permits(detail.data.value,'SHIP')" label-position="top" @submit.prevent="ship"><div class="notice">整单发货不能拆分；同一物流请求重试沿用原幂等键。</div><ElFormItem label="承运商" required><ElInput v-model="carrier" maxlength="100"/></ElFormItem><ElFormItem label="物流单号" required><ElInput v-model="tracking" maxlength="100"/></ElFormItem><Feedback :error="command.error.value"/><ElButton type="primary" native-type="submit" :disabled="!carrier.trim()||!tracking.trim()" :loading="command.busy.value">确认发货</ElButton></ElForm><ElButton @click="detail.reload">刷新详情</ElButton></template></ElDialog></template>

